MONTECARLO:
           NAMES = x1-x3 m1-m3 y1-y3;
           NOBSERVATIONS = 500;
           NREPS = 1000;
            SAVE = longMedNRI[#]_*.DAT;
            RESULTS=longMedNRI[#].txt;

          MODEL POPULATION:

          lx1 by x1@1;
          x1@0;
          lx2 by x2@1;
          x2@0;
          lx3 by x3@1;
          x3@0;

          lm1 by m1@1;
          m1@0;
          lm2 by m2@1;
          m2@0;
          lm3 by m3@1;
          m3@0;

          ly1 by y1@1;
          y1@0;
          ly2 by y2@1;
          y2@0;
          ly3 by y3@1;
          y3@0;

          !Correlations between first Indicator Disturbances
          lx1 WITH lm1*.3;
          lx1 WITH ly1*.3;
          ly1 WITH lm1*.3;

          !Autoregressive Paths Between Indicator Disturbances

          lx2 on lx1*.8;
          lx3 on lx2*.8;

          lm2 on lm1*.3;
          lm3 on lm2*.3;

          ly2 on ly1*.7;
          ly3 on ly2*.7;

          !Cross-Lagged Pattern Between Disturbances
          lm2 on lx1*.6(a1);
          lm3 on lx2*.6(a2);

          ly2 on lm1*.6(b1);
          ly3 on lm2*.6(b2);

          !Direct Effect
          ly3 on lx1*.30(c1);

          !Random Intercepts
          intx*.16;
          intm*.16;
          inty*.16;

          intx BY x1@1 x2@1 x3@1;
          intm BY m1@1 m2@1 m3@1;
          inty BY y1@1 y2@1 y3@1;

          !Variance of Disturbances

          lx1*1;
          lx2*.36;
          lx3*.36;

          lm1*1;
          lm2*.55;
          lm3*.55;

          ly1*1;
          ly2*.15;
          ly3*.15;

          intx with intm*.096;
          intx with inty*.096;
          intm with inty*.096;

          intx intm inty with lx1@0 lm1@0 ly1@0;
          intx intm inty with lx2@0 lm2@0 ly2@0;
          intx intm inty with lx3@0 lm3@0 ly3@0;

          MODEL:

          !Correlations between first Indicator Disturbances
          x1 WITH m1*.3;
          x1 WITH y1*.3;
          y1 WITH m1*.3;

          !Autoregressive Paths Between Indicator Disturbances

          x2 on x1*.8;
          x3 on x2*.8;

          m2 on m1*.3;
          m3 on m2*.3;

          y2 on y1*.7;
          y3 on y2*.7;

          !Cross-Lagged Pattern Between Disturbances
          m2 on x1*.6 (a1);
          m3 on x2*.6 (a2);

          y2 on m1*.6 (b1);
          y3 on m2*.6 (b2);

          y3 on x1*.30 (c1);

          !Variance of Disturbances

          x1*1;
          x2*.36;
          x3*.36;

          m1*1;
          m2*.55;
          m3*.55;

          y1*1;
          y2*.15;
          y3*.15;

           ! Intercept

          intx*.16;
          intm*.16;
          inty*.16;

          intx BY x1@1 x2@1 x3@1;
          intm BY m1@1 m2@1 m3@1;
          inty BY y1@1 y2@1 y3@1;

          intx with intm*.096;
          intx with inty*.096;
          intm with inty*.096;

         !x2 m2 y2 with  x2 m2 y2;
         !x3 m3 y3 with  x3 m3 y3;

        model constraints:
        new(ab*.36);
        ab = a1*b2;

          OUTPUT:
          TECH9;

